function rmEsc(v){return String(v).replace(/[&<>"']/g,rmC=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[rmC]));}
function rmBtn(t,a,k='',disabled=false,reason=''){return `<span class="stack" style="gap:4px;align-items:flex-start"><button type="button" class="btn ${k}" onclick="${rmEsc(a)}" ${disabled?'disabled':''}>${t}</button>${disabled?`<span class="muted xs">${rmEsc(reason)}</span>`:''}</span>`;}
function rmKV(rows){return `<dl class="kv">${rows.map(rmR=>`<dt>${rmR[0]}</dt><dd>${rmR[1]}</dd>`).join('')}</dl>`;}
function rmTable(h,rows){return `<div class="table-wrap"><table><thead><tr>${h.map(rmH=>`<th>${rmH}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${h.length}"><div class="empty">暂无记录</div></td></tr>`}</tbody></table></div>`;}
function rmSet(k,v){rmState[k]=v;route();}
function rmChips(k,values){return `<div class="row wrap">${values.map(rmX=>`<button type="button" class="chip ${rmState[k]===rmX?'on':''}" aria-pressed="${rmState[k]===rmX}" onclick="rmSet('${k}',${typeof rmX==='number'?rmX:JSON.stringify(rmX).replace(/"/g,'&quot;')})">${rmX}</button>`).join('')}</div>`;}
function rmModal(t,b,f=''){openModal(`<div class="stack" style="padding:24px"><div class="row"><h3 class="grow">${t}</h3>${rmBtn('关闭','closeModal()','ghost sm')}</div>${b}<div class="row wrap">${f}</div></div>`,true);}
function rmAudit(t){rmState.audit.unshift('刚刚 · 你 · '+t+' · EX-9080');}
function rmAuthenticate(action){rmModal('需重新认证',`<div class="note warn">原型演示：确认你是人类并完成重新认证。真实部署由认证服务验证；Agent 不可代办。</div><label class="row"><input id="rmAuth" type="checkbox">你确认本次敏感操作</label>`,rmBtn('模拟认证并继续',`rmAuthComplete('${action}')`,'primary'));}
function rmAuthComplete(action){if(!document.getElementById('rmAuth').checked)return toast('请确认本次敏感操作');if((action.startsWith('setting:')||action.startsWith('disconnect:'))&&!rmState.owner)return toast('仅机器所有者可操作');rmState.reauth=true;rmState.idleUntil=Date.now()+300000;closeModal();if(action==='take'){rmState.taken=true;rmAudit('暂停执行并人工接管');}else if(action.startsWith('setting:')){const rmKey=action.split(':')[1];if(!rmState.owner)return toast('仅机器所有者可改');rmState[rmKey]=!rmState[rmKey];if(rmKey==='terminal'&&!rmState.terminal){rmState.mode='只读观看';rmState.reauth=false;clearTimeout(rmState.idleTimer);}rmAudit('修改远程访问设置：'+rmKey);}else if(action.startsWith('disconnect:')){rmState.sessions=rmState.sessions.filter(rmS=>rmS.id!==Number(action.split(':')[1]));rmAudit('强制断开远程会话');}else if(action.startsWith('revoke:')){const rmS=rmState.shares.find(rmS=>rmS.id===Number(action.split(':')[1]));if(rmS)rmS.status='已撤销';rmAudit('撤销甲方分享');}route();}
function rmDanger(t,consequence,action){rmModal(t,`<div class="note danger">${consequence}需重新认证。</div>`,rmBtn('重新认证并确认',`rmAuthenticate('${action}')`,'danger'));}
function rmShare(){rmModal('分享给甲方 '+rmV,`<label class="stack">选择预览项<select id="rmShareItem" style="${rmStyle}">${rmItems.map(rmX=>`<option value="${rmX[0]}" ${rmX[0]===rmState.item?'selected':''}>${rmX[1]}${['video','novel'].includes(rmX[0])?'（v1.1）':''}</option>`).join('')}</select></label><label class="stack">有效期<select id="rmDays" style="${rmStyle}"><option value="1">1 天</option><option value="3">3 天</option><option value="7">7 天</option></select></label><span class="badge b-info">只读</span><div class="note info">提交后待批准，需有权限的人批准，Agent 不能批准。不暴露内部记录；分享用于查看进度，不代表交付或验收。</div>`,rmBtn('提交审批','rmShareSubmit()','primary'));}
function rmShareSubmit(){const rmI=rmItems.find(rmX=>rmX[0]===document.getElementById('rmShareItem').value);rmState.shares.push({id:rmState.shares.length+1,item:rmI[1],days:Number(document.getElementById('rmDays').value),status:'待批准',visits:0});rmAudit('申请甲方只读分享');closeModal();route();toast('已进入待批准');}
function rmApprove(id){rmModal('人工批准分享',`<div class="note info">原型身份：你是有分享批准权限的人。Agent 不能批准；批准后才生成只读链接，有效期从批准时开始。</div>`,rmBtn('批准',`rmApproveSave(${id})`,'primary'));}
function rmApproveSave(id){rmState.shares.find(rmS=>rmS.id===id).status='已批准';rmAudit('人工批准甲方分享');closeModal();route();}
function rmShares(){return card('甲方分享与审批 '+rmV,rmTable(['预览项 / 状态','只读链接','有效期 / 访问次数','操作'],rmState.shares.map(rmS=>`<tr><td>${rmS.item}<br><span class="badge ${rmS.status==='待批准'?'b-warn':'b-info'}">${rmS.status}</span></td><td class="mono">${rmS.status==='已批准'?rmEsc('s-7f3k9q2m'+rmS.id+'.<预览域名>'):'尚无可访问链接'}</td><td>${rmS.days} 天${rmS.status==='已批准'?'（批准起算，剩余 '+rmS.days+' 天）':''}<br>${rmS.visits} 次</td><td>${rmS.status==='待批准'?rmBtn('有权限的人批准',`rmApprove(${rmS.id})`,'sm'):rmBtn('撤销',`rmDanger('撤销分享','甲方链接立即失效，已有访问将被终止。','revoke:${rmS.id}')`,'danger sm',rmS.status==='已撤销','分享已经撤销')}</td></tr>`))+`<p class="muted small">不暴露内部记录。链接可撤销、到期失效，申请、批准和访问均写入审计。</p>`);}
function rmPreview(){const rmX=rmItems.find(rmX=>rmX[0]===rmState.item);return card('预览版本与状态',`<div class="stack">${rmChips('version',['当前工作区','声明提交 9f3c2a1（隔离副本重启）'])}<b>状态预览</b>${rmChips('status',['正常','启动中','启动失败','已休眠','空'])}<div class="note info">预览用于查看进度，不作为验收证据；验收以平台截图与验证器为准。</div></div>`)+`<div class="grid g12"><div class="c3">${card('预览列表',`<div class="stack">${rmItems.map(rmI=>rmBtn(`${rmI[1]} ${['video','novel'].includes(rmI[0])?rmV:''}<span class="muted xs">${rmI[2]}</span>`,`rmSet('item','${rmI[0]}')`,rmState.item===rmI[0]?'primary rm-wide':'ghost rm-wide')).join('')}</div><div class="sep"></div><p class="small">网页：平台按项目宪法启动，健康检查 <span class="mono">/</span>。</p><p class="small">接口：Agent 上报，已校验属于本执行的进程。</p><p class="muted xs">产物只读流式读取，不启动服务。文件变化推送刷新。</p>`)}</div><div class="c9">${card(rmX[1]+(['video','novel'].includes(rmX[0])?' '+rmV:''),rmPreviewBody())}</div></div>`+rmShares();}
function rmPreviewBody(){if(!rmState.preview)return '<div class="note warn">此机器未开启「允许远程预览」，请联系机器所有者。</div>';if(rmState.tunnel!=='正常')return '<div class="note warn">隧道重连中，预览暂不可用；执行仍在机器上继续。</div>';if(rmState.status==='空')return '<div class="empty">当前版本暂无预览项，等待服务登记或产物生成。</div>';if(rmState.status==='启动中')return '<div class="note info">启动中（健康检查中） · 端口 5173 · GET / · 第 2 次探测</div>';if(rmState.status==='启动失败')return `<div class="note danger">启动失败：端口未就绪 · 5173 · 健康检查未通过</div><pre class="code">日志尾部：\n启动进程已退出，退出码 1\n依赖未安装，端口 5173 未监听</pre>${rmBtn('重新启动并检查',"rmSet('status','启动中')")}`;if(rmState.status==='已休眠')return `<div class="note warn">已休眠：空闲 30 分钟，预览服务已自动停止。</div>${rmBtn('唤醒',"rmSet('status','启动中')",'primary')}`;
 const rmToolbar=`<div class="row wrap">${rmBtn('刷新',"toast('已请求当前版本刷新')",'sm')}${rmBtn('新窗口打开','rmNewWindow()','sm')}${rmBtn('复制内部链接','rmCopy()','sm')}${rmBtn('分享给甲方 '+rmV,'rmShare()','primary sm')}</div>`;
 if(rmState.item==='web')return `<div class="stack">${rmToolbar}<span class="mono small">${rmEsc('p-7f3k9q2m.<预览域名>')}</span>${rmChips('width',[375,768,1440])}<div style="overflow:auto;padding:16px"><div style="width:${rmState.width}px;max-width:100%;min-height:300px;margin:auto;border:1px solid var(--border);border-radius:16px;padding:24px"><div class="row">${I('receipt')}<b>账单中心</b></div><div class="sep"></div><h3>账单导出</h3><p>账期：2026 年 10 月</p><p>字段：账期、金额、税额 · 128 条</p>${rmBtn('导出 CSV',"rmSet('item','csv')",'primary')}<p class="muted small">网页预览占位 · 设备宽度 ${rmState.width} 像素</p></div></div><p class="muted xs">登录与项目执行读取权限换取预览域短期会话；独立来源隔离非可信页面。</p></div>`;
 if(rmState.item==='api')return `<div class="stack">${rmToolbar}<b>OpenAPI 调试台</b><label class="stack">端点<select style="${rmStyle}" onchange="rmSet('endpoint',this.value)">${['GET /api/exports','POST /api/exports'].map(rmE=>`<option ${rmState.endpoint===rmE?'selected':''}>${rmE}</option>`).join('')}</select></label><label class="stack">账期参数<input id="rmPeriod" style="${rmStyle}" value="2026-10" type="month"></label>${rmBtn('发送示例请求','rmApiSend()','primary')}<pre class="code">${rmEsc(rmState.response||'响应示例：200\n{"格式":"CSV","条数":128,"文件":"exports/billing.csv"}')}</pre><span class="muted small">端口 8080 · 仅本执行进程 · 请求在原型中模拟</span></div>`;
 if(rmState.item==='video')return `<div class="stack">${rmToolbar}<div class="empty" style="min-height:220px">${I('film')}播放器占位 · ${rmState.playing?'播放中':'已暂停'} · ${rmState.time} 秒 / 84 秒</div>${rmBtn(rmState.playing?'暂停':'播放',`rmSet('playing',${!rmState.playing})`,'primary')}<label class="stack">时间轴<input type="range" min="0" max="84" value="${rmState.time}" oninput="rmState.time=Number(this.value);document.getElementById('rmTime').textContent=this.value+' 秒'"><span id="rmTime">${rmState.time} 秒</span></label><div class="note info">成片较大，已由执行机生成低清代理</div><b>候选镜头对比 · 00:12–00:18</b>${rmChips('shot',['候选 A','候选 B'])}${rmKV([['候选 A','推近镜头 · 6 秒 · 当前使用'],['候选 B','全景镜头 · 6 秒 · 备选'],['正在查看',rmState.shot]])}</div>`;
 if(rmState.item==='novel')return `<div class="stack">${rmToolbar}${rmChips('chapter',[1,2,3])}<h3>第 ${rmState.chapter} 章 · 潮水来信</h3><p>她打开窗，看见潮水带来了<span class="hl">新的信件</span>。</p><p>她把信放在桌上，<span class="hl">决定等到天亮再出发</span>。</p><div class="note info">与上一版差异：新增高亮文字；删除「立刻出发」。写完一章自动刷新。</div><span class="muted small">chapters/0${rmState.chapter}.md · 当前版 1,280 字 · 上一版 1,192 字</span></div>`;
 return `<div class="stack">${rmToolbar}<div class="empty" style="min-height:230px">${I(rmState.item==='image'?'image':'file-text')}${rmState.item==='pdf'?'PDF 查看器占位 · 第 1 / 3 页':rmState.item==='image'?'图片查看器占位 · 1440 × 900':'文档查看器 · CSV'}</div>${rmState.item==='csv'?'<pre class="code">账期,金额,税额\n2026-10,1200.00,72.00</pre>':''}<span class="small">工作区产物 · 只读 · 文件改变后自动刷新</span></div>`;
}
function rmNewWindow(){rmModal('独立预览窗口',`<div class="note info">预览域名来自部署配置，原型不打开未配置的外部地址。</div><p class="mono">${rmEsc('https://p-7f3k9q2m.<预览域名>')}</p>${rmPreviewBody().replace(/<div class="row wrap">[\s\S]*?<\/div>/,'')}`);}
async function rmCopy(){const rmLink=location.href;try{await navigator.clipboard.writeText(rmLink);toast('内部工作区链接已复制，访问仍需项目权限');}catch(rmError){rmModal('复制内部链接',`<label class="stack">请选择并复制<input readonly style="${rmStyle}" value="${rmEsc(rmLink)}"></label>`);}}
function rmApiSend(){const rmP=document.getElementById('rmPeriod').value;if(!/^\d{4}-\d{2}$/.test(rmP))return toast('请填写账期');rmState.response=`模拟响应：${rmState.endpoint.startsWith('POST')?'201':'200'}\n`+JSON.stringify({账期:rmP,格式:'CSV',条数:128,文件:'exports/billing.csv'},null,2);route();}
function rmTerminal(){const rmReasons=[!rmState.terminal?'此机器未开启「允许远程终端」（工作站默认关闭，只有机器所有者能开）':'',!rmState.permission?'你没有交互终端权限':'',!rmState.reauth?'需要重新认证':''].filter(Boolean);return card('终端模式',`${rmChips('mode',['只读观看','交互 Shell'])}<p>交互 Shell ${rmV} · 仅人类、独立权限、不可委托</p>`)+card('会话输出',rmState.mode==='只读观看'?`<pre class="code mono">10:12:01 Ada · 工作目录 ${rmExecution.cwd}\n10:12:04 正在实现 CSV 导出\n10:12:08 已生成 exports/billing.csv\n10:12:12 等待下一条执行事件</pre><p class="muted small">只读观看 Agent 会话输出流，不发送输入。</p>`:rmReasons.length?`<div class="note warn"><b>交互模式不可用</b><ul>${rmReasons.map(rmR=>`<li>${rmR}</li>`).join('')}</ul></div>${rmBtn('打开交互 Shell','rmShell()','primary',true,rmReasons.join('；'))}`:`<div class="note warn">全程录制并写入审计</div><p>工作目录锁定在执行工作区：<span class="mono">${rmExecution.cwd}</span> · 空闲超时倒计时：<span id="rmIdle">05:00</span></p><pre id="rmShellOutput" class="code mono">你已连接到隔离工作区 Shell（模拟）\n${rmExecution.cwd} $</pre><label class="stack">命令<input id="rmCommand" style="${rmStyle}" placeholder="输入 pwd 或 ls" onkeydown="if(event.key==='Enter')rmShell()"></label>${rmBtn('发送命令','rmShell()','primary')}`)+card('权限与会话状态预览',`<div class="row wrap">${rmBtn('前往机器设置',"go('machine-access/studio-mini')")}${rmBtn(rmState.permission?'模拟撤回终端权限':'模拟授予你终端权限',`rmSet('permission',${!rmState.permission})`)}${rmBtn('重新认证',"rmAuthenticate('terminal')")}</div><p class="muted small">原型权限模拟不修改真实授权。关闭页面不会终止 Agent 执行。</p>`);}
function rmShell(){if(!rmState.terminal||!rmState.permission||!rmState.reauth)return toast('交互终端条件未满足');const rmInput=document.getElementById('rmCommand'),rmCmd=rmInput.value.trim();if(!rmCmd)return;document.getElementById('rmShellOutput').textContent+='\n$ '+rmCmd+'\n'+(rmCmd==='pwd'?rmExecution.cwd:rmCmd==='ls'?Object.keys(rmFiles).filter(rmF=>rmF!=='.env').join('  '):'模拟 Shell：命令已录制，不执行真实命令');rmInput.value='';rmAudit('交互终端输入已录制');rmState.idleUntil=Date.now()+300000;rmIdleTick();}
function rmIdleTick(){clearTimeout(rmState.idleTimer);if(rmState.tab!=='终端'||rmState.mode!=='交互 Shell')return;const rmEl=document.getElementById('rmIdle');if(!rmEl)return;const rmLeft=Math.max(0,Math.ceil((rmState.idleUntil-Date.now())/1000));rmEl.textContent=Math.floor(rmLeft/60)+':'+String(rmLeft%60).padStart(2,'0');if(!rmLeft){rmState.idleUntil=null;rmState.reauth=false;rmAudit('交互终端空闲超时断开');route();return;}rmState.idleTimer=setTimeout(rmIdleTick,1000);}
function rmFilesPage(){const rmSecret=rmState.file==='.env',rmCan=rmState.taken&&rmState.editing;return card('工作区目录树',`<div class="row wrap">${Object.keys(rmFiles).map(rmF=>rmBtn(rmEsc(rmF),`rmSet('file','${rmF}')`,rmState.file===rmF?'primary sm':'ghost sm')).join('')}</div><p class="muted small">路径仅限 ${rmExecution.cwd}；.env 等密钥文件已屏蔽。符号链接不得越出工作区。</p>`)+card('文件查看与下载',`<b class="mono">${rmState.file}</b><pre class="code">${rmEsc(rmFiles[rmState.file])}</pre><div class="row wrap">${rmBtn('下载','rmDownload()','',rmSecret,'密钥文件已屏蔽，不可下载')}${rmBtn('编辑 '+rmV,'rmEdit()','',!rmCan||rmSecret,rmSecret?'密钥文件已屏蔽':!rmState.taken?'先暂停执行或人工接管':'此机器未允许人工接管后编辑文件')}${rmBtn('上传 '+rmV,'rmUpload()','',!rmCan,!rmState.taken?'先暂停执行或人工接管':'此机器未允许人工接管后编辑文件')}</div>`)+card('与基线提交的差异',rmSecret?'<div class="note warn">已屏蔽，不展示密钥差异。</div>':`<p>基线：8b71d02 · 当前工作区 · ${rmState.file}</p><pre class="code">${rmState.file==='src/export.ts'?'- format = "json"\n+ format = "csv"\n+ fields = ["账期", "金额", "税额"]':'新增产物 · 基线中不存在'}</pre>`)+card('执行写锁与人工提交',`<span class="badge ${rmState.taken?'b-warn':'b-info'}">${rmState.taken?'已暂停 · 你已人工接管':'运行中 · Agent 持有写锁'}</span><div class="row wrap">${rmBtn('暂停并人工接管',"rmDanger('暂停并人工接管','Agent 将暂停写入，你将取得工作区写锁。','take')",'danger',rmState.taken,'你已接管')}${rmBtn('前往文件编辑设置',"go('machine-access/studio-mini')")}</div><p>保存必须填写提交说明，记为人工提交，不代表 Agent 已声明完成（未验证）。</p>${rmState.commits.map(rmC=>`<div class="note ok">${rmEsc(rmC)}</div>`).join('')}`);}
function rmDownload(){if(rmState.file==='.env')return toast('密钥文件已屏蔽');const rmURL=URL.createObjectURL(new Blob([rmFiles[rmState.file]],{type:'text/plain;charset=utf-8'})),rmA=document.createElement('a');rmA.href=rmURL;rmA.download=rmState.file.split('/').pop()+(['pdf','png','mp4'].includes(rmState.file.split('.').pop())?'.模拟说明.txt':'');rmA.click();setTimeout(()=>URL.revokeObjectURL(rmURL),1000);rmAudit('下载文件 '+rmState.file);}
function rmEdit(){if(!rmState.taken||!rmState.editing||rmState.file==='.env')return toast('文件编辑条件未满足');rmModal('编辑文件 '+rmV,`<p class="mono">${rmState.file}</p><label class="stack">文件内容<textarea id="rmContent" rows="7" style="${rmStyle}">${rmEsc(rmFiles[rmState.file])}</textarea></label><label class="stack">提交说明（必填）<input id="rmMessage" style="${rmStyle}" maxlength="200"></label>`,rmBtn('保存为人工提交',"rmSaveFile(false)",'primary'));}
function rmUpload(){if(!rmState.taken||!rmState.editing)return toast('先暂停执行或人工接管，并开启文件编辑');rmModal('上传文件 '+rmV,`<label class="stack">选择 UTF-8 文本文件（原型）<input id="rmUploadFile" type="file" accept=".txt,.md,.csv,.ts,.json"></label><label class="stack">提交说明（必填）<input id="rmMessage" style="${rmStyle}" maxlength="200"></label><div class="note info">仅上传至工作区 uploads/，密钥文件不可上传。</div>`,rmBtn('上传并记录人工提交',"rmSaveFile(true)",'primary'));}
async function rmSaveFile(upload){if(!rmState.taken||!rmState.editing)return toast('文件写入条件未满足');const rmMessage=document.getElementById('rmMessage').value.trim();if(!rmMessage)return toast('请填写提交说明');let rmPath=rmState.file,rmText;if(upload){const rmFile=document.getElementById('rmUploadFile').files[0];if(!rmFile)return toast('请选择文件');if(!/^[\w\u4e00-\u9fff-]+\.(txt|md|csv|ts|json)$/i.test(rmFile.name)||rmFile.size>1048576)return toast('仅支持 1 MiB 内的文本文件，禁止密钥与路径穿越');rmPath='uploads/'+rmFile.name;rmText=await rmFile.text();}else rmText=document.getElementById('rmContent').value;rmFiles[rmPath]=rmText;rmState.file=rmPath;rmState.commits.unshift('人工提交 · 你 · '+rmMessage+' · '+rmPath);rmAudit('保存人工提交：'+rmMessage);closeModal();route();toast('已保存为人工提交');}
PAGES['workspace']=(arg)=>{if(arg&&arg!==rmExecution.id)return head('远程工作区','执行不存在','此原型提供 EX-9080 的独立样例。',rmBtn('查看 EX-9080',"go('workspace/EX-9080')"));clearTimeout(rmState.idleTimer);if(rmState.tab==='终端'&&rmState.mode==='交互 Shell'&&rmState.terminal&&rmState.permission&&rmState.reauth){rmState.idleUntil=rmState.idleUntil||Date.now()+300000;setTimeout(rmIdleTick,0);}return head('远程工作区',rmExecution.id+' · '+rmExecution.title,`${rmExecution.work} · ${rmExecution.project} · ${rmExecution.actor} · studio-mini（工作站）`, `<span class="badge b-info">${rmState.taken?'已暂停 · 人工接管':'运行中'}</span><span class="badge ${rmState.tunnel==='正常'?'b-ok':'b-warn'}">隧道连接：${rmState.tunnel}</span>`)+card('执行与访问边界',rmKV([['执行 / 工作项','EX-9080 / BIL-142'],['机器 / 类型','studio-mini / 工作站'],['声明提交','9f3c2a1 · 已声明完成（未验证）'],['隧道','执行机主动出站，多路复用；不开放入站端口'],['预览生命周期','空闲 30 分钟休眠；受最长存活配置约束；执行结束即停止']])+rmChips('tunnel',['正常','重连中']))+`<div class="tabs wrap" role="tablist">${['预览','终端','文件'].map(rmT=>`<button role="tab" aria-selected="${rmState.tab===rmT}" class="${rmState.tab===rmT?'on':''}" onclick="rmSet('tab','${rmT}')">${rmT}</button>`).join('')}</div>`+(rmState.tab==='预览'?rmPreview():rmState.tab==='终端'?rmTerminal():rmFilesPage());};
PAGES['runners']=()=>head('机器','执行机类型与执行池','所有执行机通过主动出站隧道接入，不需要开放入站端口。')+`<div class="grid g12"><div class="c6">${card('工作站',rmKV([['运行形态','桌面程序'],['机器','studio-mini · macOS · 在线'],['所有者','你'],['远程终端','默认关闭，仅机器所有者可改，需重新认证']])+rmBtn('远程访问设置',"go('machine-access/studio-mini')",'primary'))}</div><div class="c6">${card('服务器常驻',rmKV([['运行形态','无界面守护进程'],['认证','机器专属服务账号'],['安装方式','systemd / docker'],['隧道','出站连接 · 预览、终端、文件共用']])+`<pre class="code"># systemd（示例，凭证由受保护配置注入）\n[Service]\nExecStart=/usr/local/bin/machine-runner daemon\nRestart=on-failure\n\n# docker（示例，使用部署配置提供的镜像）\ndocker run -d --restart unless-stopped \\\n  --env-file /etc/runner/credentials \\\n  -v /srv/workspaces:/workspaces &lt;执行机镜像&gt;</pre>`)}</div></div>`+card('k8s 执行池 '+rmV,rmKV([['运行方式','每次执行一个临时 Pod，执行结束回收'],['命名空间','execution-pool'],['镜像','<执行机镜像>:stable'],['最少 / 最多 Pod','1 / 8'],['资源配额','16 核 CPU / 32 GiB 内存'],['单 Pod','2 核 CPU / 4 GiB 内存']])+rmTable(['当前 Pod','所属执行','状态'],['<tr><td>runner-ex-9080</td><td>EX-9080（池调度示意，非当前工作站实例）</td><td>运行中</td></tr>','<tr><td>runner-warm-01</td><td>等待执行</td><td>就绪</td></tr>'])+`<div class="note info">自动扩缩容示意：队列 0 → 保留 1 Pod；队列 4 → 扩至 4 Pod；最多 8 Pod；空闲 Pod 回收。工作区与预览随执行隔离。</div>`)+card('预览网关',rmKV([['预览域名（部署配置）',rmEsc('<预览域名>')],['泛域名证书','有效 · 部署配置提供 · 剩余 62 天'],['域名隔离','独立可注册域，每个预览随机标签'],['带宽配额','使用 12 / 100 Mbps'],['并发配额','使用 3 / 20'],['传输支持','HTTP/1.1、WebSocket 热更新、SSE、范围请求']])+`<label class="row"><input type="checkbox" ${rmState.path?'checked':''} onchange="rmSet('path',this.checked)">路径模式回退</label>${rmState.path?'<div class="note warn">部分应用可能无法正常预览。回退仍使用独立预览域，不使用控制台来源。</div>':'<p class="muted small">无泛域名 DNS 时可启用路径模式回退；部分应用可能无法正常预览。</p>'}`);
function rmSetting(key,title,v11=false){return `<div class="row wrap"><label class="grow row"><input type="checkbox" ${rmState[key]?'checked':''} ${!rmState.owner?'disabled':''} onclick="event.preventDefault();rmAuthenticate('setting:${key}')">${title} ${v11?rmV:''}</label><span class="badge ${rmState[key]?'b-ok':'b-stale'}">${rmState[key]?'已开启':'已关闭'}</span></div><p class="muted xs">仅机器所有者可改，需重新认证。${!rmState.owner?'你不是机器所有者，开关不可用。':''}</p>`;}
function rmAccessBody(m){if(!m||m.n!=='studio-mini')return `<div class="note info">此原型只为 studio-mini 提供远程访问设置样例。</div>`+rmBtn('查看 studio-mini 的远程访问',"go('machine-access/studio-mini')");return card('远程访问开关',rmSetting('preview','允许远程预览')+rmSetting('terminal','允许远程终端')+rmSetting('editing','允许人工接管后编辑文件',true)+`<div class="note warn">工作站远程终端默认关闭。关闭权限后相关访问不再可用；交互 Shell 还需人类独立权限与重新认证。</div><div class="row wrap">${rmBtn(rmState.owner?'模拟非所有者身份':'恢复机器所有者身份',`rmSet('owner',${!rmState.owner})`)}${rmBtn('返回远程工作区',"go('workspace/EX-9080')")}</div>`)+card('当前远程会话',rmTable(['类型','谁','何时 / 执行','操作'],rmState.sessions.map(rmS=>`<tr><td>${rmS.type}</td><td>${rmS.who}</td><td>${rmS.time} · EX-9080</td><td>${rmBtn('强制断开',`rmDanger('强制断开','此远程会话立即结束，未保存的交互输入可能丢失，不会停止 Agent 执行。','disconnect:${rmS.id}')`,'danger sm',!rmState.owner,'仅机器所有者可强制断开')}</td></tr>`)))+card('最近审计',rmState.audit.map(rmA=>`<div class="small" style="padding:8px 0">${rmEsc(rmA)}</div>`).join('')+`<p class="muted xs">记录主体、动作、执行与机器；交互终端全程录制，文件写入记录人工提交。</p>`);}
PAGES['machine-access']=(arg)=>{const m=MACHINES.find(x=>x.n===arg||x.id===arg)||MACHINES[0];flState.mtab=flState.mtab||{};flState.mtab[m.id]=7;setTimeout(()=>location.replace('#/machine/'+m.id),0);return '';};
TITLES['workspace']='远程工作区';NAVPARENT['workspace']='executions';
TITLES['runners']='执行机类型与执行池';NAVPARENT['runners']='machines';
TITLES['machine-access']='远程访问设置';NAVPARENT['machine-access']='machines';
document.head.insertAdjacentHTML('beforeend','<style>.btn.rm-wide{width:100%;justify-content:flex-start;flex-wrap:wrap;height:auto;min-height:36px;padding:6px 14px}.btn.primary .muted{color:inherit;opacity:.85}</style>');
